// === PARSE CLOUD API PAYLOAD ===
// Extrai mensagem do formato Cloud API do Meta
// Ref: https://developers.facebook.com/docs/whatsapp/cloud-api/webhooks/components

const body = $input.first().json.body || {};

// Cloud API envia array de entries
const entries = body.entry || [];
if (entries.length === 0) return [];

const results = [];

for (const entry of entries) {
  const changes = entry.changes || [];
  for (const change of changes) {
    if (change.field !== 'messages') continue;
    const value = change.value || {};
    const metadata = value.metadata || {};
    const phone_number_id = metadata.phone_number_id || '';
    const display_phone = metadata.display_phone_number || '';
    const contacts = value.contacts || [];
    const messages = value.messages || [];
    const statuses = value.statuses || [];

    // Ignora status updates (delivered, read, etc.)
    if (statuses.length > 0 && messages.length === 0) continue;

    for (const msg of messages) {
      const contact = contacts.find(c => c.wa_id === msg.from) || {};
      const profile = contact.profile || {};

      let text = '';
      let media_url = '';
      let media_id = '';
      let tipo = 'texto';

      switch (msg.type) {
        case 'text':
          text = (msg.text || {}).body || '';
          break;
        case 'image':
          media_id = (msg.image || {}).id || '';
          text = (msg.image || {}).caption || '';
          tipo = 'imagem';
          break;
        case 'audio':
          media_id = (msg.audio || {}).id || '';
          tipo = 'audio';
          break;
        case 'video':
          media_id = (msg.video || {}).id || '';
          text = (msg.video || {}).caption || '';
          tipo = 'video';
          break;
        case 'document':
          media_id = (msg.document || {}).id || '';
          text = (msg.document || {}).caption || (msg.document || {}).filename || '';
          tipo = 'documento';
          break;
        case 'location':
          const loc = msg.location || {};
          text = `Localizacao: ${loc.latitude}, ${loc.longitude}${loc.name ? ' (' + loc.name + ')' : ''}`;
          tipo = 'localizacao';
          break;
        case 'contacts':
          text = '[Contato compartilhado]';
          tipo = 'contato';
          break;
        case 'interactive':
          // WhatsApp Flows, buttons, lists
          const interactive = msg.interactive || {};
          if (interactive.type === 'button_reply') {
            text = (interactive.button_reply || {}).title || '';
          } else if (interactive.type === 'list_reply') {
            text = (interactive.list_reply || {}).title || '';
          } else if (interactive.type === 'nfm_reply') {
            // WhatsApp Flows response
            text = JSON.stringify((interactive.nfm_reply || {}).response_json || {});
          }
          tipo = 'interactive';
          break;
        case 'button':
          text = (msg.button || {}).text || '';
          tipo = 'button';
          break;
        case 'reaction':
          // Ignora reacoes
          continue;
        default:
          text = '[Tipo nao suportado: ' + msg.type + ']';
      }

      results.push({
        phone: msg.from || '',
        wa_id: msg.from || '',
        nome: profile.name || 'Lead',
        text: text,
        media_id: media_id,
        tipo: tipo,
        phone_number_id: phone_number_id,
        display_phone: display_phone,
        message_id: msg.id || '',
        timestamp: msg.timestamp ? new Date(parseInt(msg.timestamp) * 1000).toISOString() : new Date().toISOString(),
        source: 'cloud_api'
      });
    }
  }
}

if (results.length === 0) return [];
return results.map(r => ({ json: r }));

// === DOWNLOAD MEDIA (Cloud API) v2 ===
// Se a mensagem tem media_id, baixa a URL do media via Graph API.
// Bug fix v2: trocado new URL(url) por https.request(urlString) — URL global
// nao esta exposto no sandbox do n8n Code node.

const https = require('https');
const input = $input.first().json;

const CLOUD_API_TOKEN = '{{SYSTEM_USER_TOKEN}}';

if (!input.media_id) {
  return [{ json: { ...input, media_url: '' } }];
}

function httpGetJson(url, headers) {
  return new Promise((resolve, reject) => {
    const req = https.request(url, { method: 'GET', headers, timeout: 8000 }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch { resolve({ raw: data }); } });
    });
    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
    req.on('error', reject);
    req.end();
  });
}

try {
  const mediaInfo = await httpGetJson(
    'https://graph.facebook.com/v21.0/' + input.media_id,
    { 'Authorization': 'Bearer ' + CLOUD_API_TOKEN }
  );
  const mediaUrl = (mediaInfo && mediaInfo.url) || '';
  return [{ json: { ...input, media_url: mediaUrl } }];
} catch (e) {
  console.log('Media download error:', e.message);
  return [{ json: { ...input, media_url: '' } }];
}

// === RESOLVE CONTACT — Supabase bia_whatsapp_contacts ===
// Upsert contato + resolve agent_id
// v3: detecta button reply + fallback 8/9 digitos celular BR

const https = require('https');
const input = $input.first().json;

const SB_URL = '{{SUPABASE_PROJECT_REF}}.supabase.co';
const SB_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const SB_HEADERS = {
  'apikey': SB_KEY,
  'Authorization': 'Bearer ' + SB_KEY,
  'Content-Type': 'application/json',
  'Prefer': 'return=representation'
};

// Phone Number ID → default agent_id mapping
const PHONE_AGENT_MAP = {
  // Phone Number ID -> agent_id padrao desse numero.
  // 1 numero: deixe so a linha abaixo (ja substituida pelo SEU phone number id).
  // Varios numeros: adicione 1 linha por numero (ex: '<pnid_2>': 'bia-atendimento').
  '{{PHONE_NUMBER_ID}}': 'bia',
};

// Button text → agent_id mapping (template Quick Reply buttons)
const BUTTON_AGENT_MAP = {
  'saber mais': 'bia-recovery',
  'quero saber': 'bia-recovery',
  'quero saber mais': 'bia-recovery',
  'quero!': 'bia-recovery',
  'quero': 'bia-recovery',
  'formato aulas': 'bia-boas-vindas',
};

function httpReq(method, path, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body ? JSON.stringify(body) : '';
    const headers = { ...SB_HEADERS };
    if (body) headers['Content-Length'] = Buffer.byteLength(bodyStr);
    if (method === 'POST') headers['Prefer'] = 'resolution=merge-duplicates,return=representation';
    const options = { hostname: SB_URL, path: '/rest/v1/' + path, method, headers, timeout: 6000 };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch { resolve(null); } });
    });
    req.on('timeout', () => { req.destroy(); resolve(null); });
    req.on('error', () => resolve(null));
    if (body) req.write(bodyStr);
    req.end();
  });
}

// === PHONE ALT: gera formato alternativo 8/9 digitos ===
// 13 digitos (55+DDD+9+8dig) → 12 digitos (55+DDD+8dig): remove o 9
// 12 digitos (55+DDD+8dig) → 13 digitos (55+DDD+9+8dig): adiciona 9
function getAltPhone(phone) {
  if (!phone || !phone.startsWith('55')) return null;
  const local = phone.substring(2); // sem DDI
  if (local.length === 11) {
    // 11 digitos = DDD(2) + 9 + 8dig → remove o 9 (3o char)
    return '55' + local.substring(0, 2) + local.substring(3);
  } else if (local.length === 10) {
    // 10 digitos = DDD(2) + 8dig → adiciona 9 apos DDD
    return '55' + local.substring(0, 2) + '9' + local.substring(2);
  }
  return null;
}

const phone = input.phone;
if (!phone) return [];

// Detecta agent_id pelo button reply do template
const buttonAgent = (input.tipo === 'button' && input.text)
  ? BUTTON_AGENT_MAP[input.text.toLowerCase().trim()] || null
  : null;

// 1. Busca contato existente
let contact = null;
let phoneMatched = phone;
const existing = await httpReq('GET', 'bia_whatsapp_contacts?phone=eq.' + phone + '&select=*');

if (existing && existing.length > 0) {
  contact = existing[0];
} else {
  // 1b. Fallback: tenta formato alternativo 8/9 digitos
  const altPhone = getAltPhone(phone);
  if (altPhone) {
    const altExisting = await httpReq('GET', 'bia_whatsapp_contacts?phone=eq.' + altPhone + '&select=*');
    if (altExisting && altExisting.length > 0) {
      contact = altExisting[0];
      phoneMatched = altPhone;
      // Corrige o phone pro formato real do WhatsApp (autoridade)
      await httpReq('PATCH', 'bia_whatsapp_contacts?phone=eq.' + altPhone, {
        phone: phone,
        wa_id: phone
      });
      contact.phone = phone;
    }
  }
}

if (contact) {
  // Atualiza contato existente
  const updateFields = {
    last_message_at: new Date().toISOString(),
  };
  if (input.nome !== 'Lead') updateFields.nome = input.nome;
  // So corrige agent_id se esta no default 'bia' (triage) — NUNCA sobrescreve
  // agent_id que ja foi setado intencionalmente (ex: bia-boas-vindas, bia-convite)
  if (buttonAgent && contact.active_agent_id === 'bia') {
    updateFields.active_agent_id = buttonAgent;
    contact.active_agent_id = buttonAgent;
  }
  await httpReq('PATCH', 'bia_whatsapp_contacts?phone=eq.' + phone, updateFields);
} else {
  // 2. Cria contato novo — usa buttonAgent se detectado, senao default
  const defaultAgent = buttonAgent || PHONE_AGENT_MAP[input.phone_number_id] || 'bia';
  const newContact = {
    phone: phone,
    phone_number_id: input.phone_number_id,
    wa_id: input.wa_id || phone,
    nome: input.nome || 'Lead',
    active_agent_id: defaultAgent,
    last_message_at: new Date().toISOString()
  };
  const created = await httpReq('POST', 'bia_whatsapp_contacts', newContact);
  contact = (created && created.length > 0) ? created[0] : newContact;
}

// Resolve agent_id: usa o que ta no contato (permite override via recovery/boas-vindas)
const agent_id = contact.active_agent_id || PHONE_AGENT_MAP[input.phone_number_id] || 'bia';
const is_human = contact.is_human_takeover || false;

return [{ json: {
  ...input,
  subscriber_id: phone,
  agent_id: agent_id,
  is_human_takeover: is_human,
  chatwoot_contact_id: contact.chatwoot_contact_id || null,
  chatwoot_conversation_id: contact.chatwoot_conversation_id || null,
  pessoa_id: contact.pessoa_id || null,
  source: 'cloud_api'
} }];

// === SYNC HUMANO → CHATWOOT v3 ===
// Quando is_human_takeover=true, sincroniza msg do lead pro Chatwoot
// v3: suporte a midia (audio/imagem/video/documento) via multipart upload
// Bug fix: v2 mandava sempre '[media]' como content, sem anexo.

const https = require('https');
const http = require('http');

// Pega dados do Resolve Contact (vem direto do Download Media → Parse Cloud API)
const resolveData = $('Resolve Contact (Supabase)').first().json;
const phone = resolveData.phone || resolveData.subscriber_id || '';
const nome = resolveData.nome || 'Lead';
const tipo = (resolveData.tipo || 'texto').toLowerCase();
const mediaId = resolveData.media_id || '';
const mediaUrl = resolveData.media_url || '';
const textContent = resolveData.text || resolveData.mensagem || resolveData.mensagem_concatenada || '';
const agent_id = resolveData.agent_id || 'bia-recovery';
let contactId = resolveData.chatwoot_contact_id;
let conversationId = resolveData.chatwoot_conversation_id;

const CW_HOST = 'chatwoot.{{SEU_DOMINIO}}';
const CW_ACCOUNT_ID = 2;
const CW_INBOX_ID = 2;
const CW_API_TOKEN = '{{CHATWOOT_TOKEN}}';
const CLOUD_API_TOKEN = '{{SYSTEM_USER_TOKEN}}';

const TIPOS_COM_MIDIA = ['imagem', 'audio', 'video', 'documento', 'sticker'];
const EXT_MAP = {
  'image/jpeg': 'jpg', 'image/jpg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif',
  'video/mp4': 'mp4', 'video/3gpp': '3gp',
  'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'aac', 'audio/amr': 'amr',
  'application/pdf': 'pdf', 'application/zip': 'zip',
  'application/msword': 'doc',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx'
};

function cwReq(method, path, body) {
  return new Promise((resolve) => {
    const bodyStr = body ? JSON.stringify(body) : '';
    const headers = { 'Content-Type': 'application/json', 'api_access_token': CW_API_TOKEN };
    if (body) headers['Content-Length'] = Buffer.byteLength(bodyStr);
    const req = https.request({
      hostname: CW_HOST, path: '/api/v1/accounts/' + CW_ACCOUNT_ID + '/' + path,
      method, headers, timeout: 8000, rejectUnauthorized: false
    }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch { resolve(null); } });
    });
    req.on('timeout', () => { req.destroy(); resolve(null); });
    req.on('error', () => resolve(null));
    if (body) req.write(bodyStr);
    req.end();
  });
}

function getMediaUrl(mid) {
  return new Promise((resolve) => {
    const req = https.request({
      hostname: 'graph.facebook.com', path: '/v21.0/' + mid, method: 'GET',
      headers: { 'Authorization': 'Bearer ' + CLOUD_API_TOKEN }, timeout: 6000
    }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve(JSON.parse(data).url || ''); } catch { resolve(''); } });
    });
    req.on('timeout', () => { req.destroy(); resolve(''); });
    req.on('error', () => resolve(''));
    req.end();
  });
}

// v4: usa https.request(urlString, options) — sem new URL()
function downloadBinary(url, headers) {
  return new Promise((resolve, reject) => {
    try {
      const isHttp = url.startsWith('http://');
      const mod = isHttp ? http : https;
      const req = mod.request(url, { method: 'GET', headers, timeout: 15000 }, (res) => {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
          let loc = res.headers.location;
          if (loc.startsWith('/')) {
            const m = url.match(/^(https?:\/\/[^/]+)/);
            if (m) loc = m[1] + loc;
          }
          return downloadBinary(loc, headers).then(resolve).catch(reject);
        }
        const chunks = [];
        res.on('data', c => chunks.push(c));
        res.on('end', () => resolve({ buffer: Buffer.concat(chunks), contentType: res.headers['content-type'] || 'application/octet-stream', status: res.statusCode }));
      });
      req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
      req.on('error', reject);
      req.end();
    } catch (e) { reject(e); }
  });
}

function cwSendWithAttachment(convId, content, fileBuffer, fileName, contentType) {
  return new Promise((resolve) => {
    const boundary = '----n8nBoundary' + Date.now() + Math.random().toString(36).slice(2);
    const parts = [];
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="content"\r\n\r\n${content || ''}\r\n`));
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="message_type"\r\n\r\nincoming\r\n`));
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="private"\r\n\r\nfalse\r\n`));
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="attachments[]"; filename="${fileName}"\r\nContent-Type: ${contentType}\r\n\r\n`));
    parts.push(fileBuffer);
    parts.push(Buffer.from(`\r\n--${boundary}--\r\n`));
    const body = Buffer.concat(parts);
    const req = https.request({
      hostname: CW_HOST,
      path: `/api/v1/accounts/${CW_ACCOUNT_ID}/conversations/${convId}/messages`,
      method: 'POST',
      headers: { 'Content-Type': `multipart/form-data; boundary=${boundary}`, 'Content-Length': body.length, 'api_access_token': CW_API_TOKEN },
      timeout: 15000, rejectUnauthorized: false
    }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve({ status: res.statusCode, body: JSON.parse(data) }); } catch { resolve({ status: res.statusCode }); } });
    });
    req.on('timeout', () => { req.destroy(); resolve(null); });
    req.on('error', () => resolve(null));
    req.write(body);
    req.end();
  });
}

try {
  // 1. Resolve contato/conversa
  if (!contactId) {
    const sr = await cwReq('GET', 'contacts/search?q=' + encodeURIComponent('+' + phone) + '&include_contacts=true', null);
    if (sr && sr.payload && sr.payload.length > 0) { contactId = sr.payload[0].id; }
    else {
      const cr = await cwReq('POST', 'contacts', { name: nome, phone_number: '+' + phone, identifier: phone });
      if (cr && cr.payload) contactId = cr.payload.contact.id;
    }
  }
  if (contactId && !conversationId) {
    try {
      const ec = await cwReq('GET', 'contacts/' + contactId + '/conversations', null);
      if (ec && ec.payload && ec.payload.length > 0) {
        const oc = ec.payload.find(c => c.status === 'open') || ec.payload[0];
        conversationId = oc.id;
      }
    } catch (e) {}
    if (!conversationId) {
      const nc = await cwReq('POST', 'conversations', { contact_id: contactId, inbox_id: CW_INBOX_ID, status: 'open' });
      if (nc && nc.id) conversationId = nc.id;
    }
  }

  // 2. Envia mensagem (com ou sem midia)
  let mediaOk = false;
  if (conversationId) {
    const isMidia = TIPOS_COM_MIDIA.includes(tipo);
    if (isMidia && (mediaId || mediaUrl)) {
      let url = mediaUrl;
      if (!url && mediaId) url = await getMediaUrl(mediaId);
      if (url) {
        try {
          let dl = await downloadBinary(url, { 'Authorization': 'Bearer ' + CLOUD_API_TOKEN, 'User-Agent': 'n8n-bia' });
          if ((!dl || !dl.buffer || dl.buffer.length === 0) && mediaId) {
            const fresh = await getMediaUrl(mediaId);
            if (fresh) dl = await downloadBinary(fresh, { 'Authorization': 'Bearer ' + CLOUD_API_TOKEN, 'User-Agent': 'n8n-bia' });
          }
          if (dl && dl.buffer && dl.buffer.length > 0) {
            const ext = EXT_MAP[dl.contentType] || 'bin';
            const fileName = `${tipo}_${Date.now()}.${ext}`;
            const r = await cwSendWithAttachment(conversationId, textContent || '', dl.buffer, fileName, dl.contentType);
            if (r && r.status >= 200 && r.status < 300) mediaOk = true;
          }
        } catch (e) { /* fallback abaixo */ }
      }
      if (!mediaOk) {
        await cwReq('POST', 'conversations/' + conversationId + '/messages', {
          content: textContent || `[${tipo} - falha ao anexar]`,
          message_type: 'incoming', private: false
        });
      }
    } else {
      // Texto puro
      await cwReq('POST', 'conversations/' + conversationId + '/messages', {
        content: textContent || '[mensagem vazia]',
        message_type: 'incoming', private: false
      });
    }
  }

  // 3. Salva IDs no Supabase
  if (contactId || conversationId) {
    const ub = {};
    if (contactId) ub.chatwoot_contact_id = contactId;
    if (conversationId) ub.chatwoot_conversation_id = conversationId;
    const sbKey = '{{SUPABASE_SERVICE_ROLE_KEY}}';
    const bs = JSON.stringify(ub);
    const r = https.request({ hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co', path: '/rest/v1/bia_whatsapp_contacts?phone=eq.' + phone, method: 'PATCH', headers: { 'apikey': sbKey, 'Authorization': 'Bearer ' + sbKey, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bs) }, timeout: 5000 });
    r.on('error', () => {});
    r.write(bs); r.end();
  }

  return [{ json: { ...resolveData, chatwoot_contact_id: contactId, chatwoot_conversation_id: conversationId, _synced_chatwoot: true, _human_takeover: true, _media_attached: mediaOk } }];
} catch (e) {
  return [{ json: { ...resolveData, _synced_chatwoot: false, _human_takeover: true, _error: e.message } }];
}

// === FILTRO AUTO-REPLY v1.4 — Cloud API Edition ===
// Mesmos patterns do WF-INBOUND original

const AUTO_REPLY_PATTERNS = [
  'estou ocupado', 'no momento nao posso', 'no momento não posso',
  'te retorno em breve', 'mensagem automatica', 'mensagem automática',
  'away message', 'out of office', 'resposta automatica', 'resposta automática',
  'automatic reply', 'currently unavailable', 'nao posso atender',
  'não posso atender', 'no momento estou', 'retornarei em breve',
  'auto-reply', 'auto reply', 'horario de atendimento', 'horário de atendimento',
  'fora do horario', 'fora do horário', 'respondemos sua mensagem',
  'retornaremos o mais breve', 'entraremos em contato',
  'nao estamos disponiveis', 'não estamos disponíveis',
  'atendimento encerrado', 'nosso horario de', 'nosso horário de',
  'mensagem sera respondida', 'mensagem será respondida',
  'volte a entrar em contato', 'entre em contato no horario',
  'entre em contato no horário', 'funcionamos de segunda',
  'nosso atendimento funciona', 'fora do expediente',
  'agradecemos sua mensagem', 'agradecemos o contato',
  'agradecemos por entrar em contato', 'obrigado por entrar em contato',
  'obrigado pelo contato', 'obrigada por entrar em contato', 'obrigada pelo contato'
];

const input = $input.first().json;
const text = (input.text || '').trim();

if (!text) return [{ json: { ...input, _auto_reply: false } }];

const msgLower = text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

for (const pattern of AUTO_REPLY_PATTERNS) {
  const patLower = pattern.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (msgLower.includes(patLower)) {
    console.log(JSON.stringify({ event: 'auto_reply_filtered', phone: input.phone, matched: pattern }));
    return [{ json: { ...input, _auto_reply: true, matched_pattern: pattern } }];
  }
}

return [{ json: { ...input, _auto_reply: false } }];

// === BUFFER E ANTI-DUPLICATA v7.0 — Supabase RPC ===
// Substitui staticData por Supabase atomic RPC (BUG-025 fix).
// buffer_message: atomic append com row lock, zero race condition.
// Anti-duplicata: $getWorkflowStaticData('node') — lightweight, sem API call.
// Fallback graceful: se Supabase falhar, msg passa direto.

const https = require('https');

const SUPA_HOST = '{{SUPABASE_PROJECT_REF}}.supabase.co';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

function supaRpc(fnName, params) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(params);
    const options = {
      hostname: SUPA_HOST,
      path: '/rest/v1/rpc/' + fnName,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'apikey': SUPA_KEY,
        'Authorization': 'Bearer ' + SUPA_KEY,
        'Content-Length': Buffer.byteLength(body)
      },
      timeout: 8000
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch { resolve({ raw: data }); }
      });
    });
    req.on('timeout', () => { req.destroy(); reject({ code: 'ETIMEDOUT' }); });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

