if (!sd.lastMessages) sd.lastMessages = {};

const dedupKey = phone + ':' + text + ':' + media_id;
const lastTs = sd.lastMessages[dedupKey] || 0;
if (now - lastTs < DEDUP_WINDOW) {
  return [{ json: { _skip: true, reason: 'duplicata', phone } }];
}
sd.lastMessages[dedupKey] = now;

// Cleanup old dedup entries (keep last 200)
const dedupKeys = Object.keys(sd.lastMessages);
if (dedupKeys.length > 200) {
  const sorted = dedupKeys.sort((a, b) => sd.lastMessages[a] - sd.lastMessages[b]);
  for (let i = 0; i < sorted.length - 200; i++) {
