// === COLETA BUFFER v7.0 — Supabase RPC ===
// collect_buffer: atomic collect com FOR UPDATE SKIP LOCKED.
// So uma execucao coleta — as demais recebem found:false e param.
// Fallback graceful: se Supabase falhar, msg original passa direto.

const https = require('https');

const SUPA_HOST = '{{SUPABASE_PROJECT_REF}}.supabase.co';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

function supaRpc(fnName, params) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(params);
    const options = {
      hostname: SUPA_HOST,
      path: '/rest/v1/rpc/' + fnName,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'apikey': SUPA_KEY,
        'Authorization': 'Bearer ' + SUPA_KEY,
        'Content-Length': Buffer.byteLength(body)
      },
      timeout: 8000
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch { resolve({ raw: data }); }
      });
    });
    req.on('timeout', () => { req.destroy(); reject({ code: 'ETIMEDOUT' }); });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

