function fetch(hostname, path, headers) {
  return new Promise((resolve, reject) => {
    const options = { hostname, path, method: 'GET', headers, timeout: 6000 };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch { resolve(null); } });
    });
    req.on('timeout', () => { req.destroy(); resolve(null); });
    req.on('error', () => resolve(null));
    req.end();
  });
}

function supa(path) {
  return fetch(SUPABASE_URL, '/rest/v1/' + path, {
    'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY
  });
}

function normalizePhone(raw) {
  const digits = (raw || '').replace(/[^0-9]/g, '');
  const variants = new Set();
  variants.add(digits);
  if (digits.startsWith('55') && digits.length >= 12) variants.add(digits.substring(2));
  else if (digits.length <= 11) variants.add('55' + digits);
  return [...variants];
}

function timeSince(dateStr) {
  if (!dateStr) return '';
  const diff = Date.now() - new Date(dateStr).getTime();
  const days = Math.floor(diff / 86400000);
  if (days < 30) return days + ' dias atras';
  if (days < 365) return Math.floor(days / 30) + ' meses atras';
  return Math.floor(days / 365) + ' ano(s) atras';
}

