  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx'
};

function cwRequest(method, path, body) {
  return new Promise((resolve) => {
    const bodyStr = body ? JSON.stringify(body) : '';
    const headers = { 'Content-Type': 'application/json', 'api_access_token': CW_API_TOKEN };
    if (body) headers['Content-Length'] = Buffer.byteLength(bodyStr);
    const options = {
      hostname: CW_HOST, path: '/api/v1/accounts/' + CW_ACCOUNT_ID + '/' + path,
      method, headers, timeout: 8000, rejectUnauthorized: false
    };
