      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        try {
          const j = JSON.parse(data);
          resolve(j.url || '');
        } catch { resolve(''); }
      });
    });
    req.on('timeout', () => { req.destroy(); resolve(''); });
    req.on('error', () => resolve(''));
    req.end();
  });
}

// Baixa binario de uma URL (segue redirects).
// v3: usa https.request(urlString, options) — sem new URL() (nao funciona no sandbox do n8n)
function downloadBinary(url, headers) {
  return new Promise((resolve, reject) => {
    try {
      const isHttp = url.startsWith('http://');
      const mod = isHttp ? http : https;
      const req = mod.request(url, { method: 'GET', headers, timeout: 15000 }, (res) => {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
          let loc = res.headers.location;
          if (loc.startsWith('/')) {
            const m = url.match(/^(https?:\/\/[^/]+)/);
            if (m) loc = m[1] + loc;
          }
          return downloadBinary(loc, headers).then(resolve).catch(reject);
        }
        const chunks = [];
        res.on('data', c => chunks.push(c));
        res.on('end', () => resolve({
          buffer: Buffer.concat(chunks),
          contentType: res.headers['content-type'] || 'application/octet-stream',
          status: res.statusCode
        }));
      });
      req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
      req.on('error', reject);
      req.end();
    } catch (e) { reject(e); }
  });
}

// Multipart POST pro Chatwoot com attachment
function cwSendWithAttachment(conversationId, content, fileBuffer, fileName, contentType) {
  return new Promise((resolve) => {
    const boundary = '----n8nBoundary' + Date.now() + Math.random().toString(36).slice(2);
    const parts = [];
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="content"\r\n\r\n${content || ''}\r\n`));
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="message_type"\r\n\r\nincoming\r\n`));
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="private"\r\n\r\nfalse\r\n`));
    parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="attachments[]"; filename="${fileName}"\r\nContent-Type: ${contentType}\r\n\r\n`));
    parts.push(fileBuffer);
    parts.push(Buffer.from(`\r\n--${boundary}--\r\n`));
    const body = Buffer.concat(parts);

    const options = {
      hostname: CW_HOST,
      path: `/api/v1/accounts/${CW_ACCOUNT_ID}/conversations/${conversationId}/messages`,
      method: 'POST',
      headers: {
        'Content-Type': `multipart/form-data; boundary=${boundary}`,
        'Content-Length': body.length,
        'api_access_token': CW_API_TOKEN
      },
      timeout: 15000,
      rejectUnauthorized: false
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve({ status: res.statusCode, body: JSON.parse(data) }); } catch { resolve({ status: res.statusCode, body: { raw: data } }); } });
    });
    req.on('timeout', () => { req.destroy(); resolve(null); });
    req.on('error', () => resolve(null));
    req.write(body);
    req.end();
  });
}

// Envia 1 media item (com retry de URL refresh se 401/expirou)
async function sendOneMedia(conversationId, item, contentText) {
  let url = item.media_url || '';
  // Se URL nao veio ou pode ter expirado, regenera via Graph API
  if (!url && item.media_id) {
    url = await getMediaUrl(item.media_id);
  }
  if (!url) return { ok: false, reason: 'no_url' };

  let dl;
  try {
    dl = await downloadBinary(url, { 'Authorization': 'Bearer ' + CLOUD_API_TOKEN, 'User-Agent': 'n8n-bia' });
  } catch (e) {
    // Fallback: regenera URL e tenta de novo
    if (item.media_id) {
      const fresh = await getMediaUrl(item.media_id);
      if (fresh) {
        try { dl = await downloadBinary(fresh, { 'Authorization': 'Bearer ' + CLOUD_API_TOKEN, 'User-Agent': 'n8n-bia' }); }
        catch (e2) { return { ok: false, reason: 'dl_failed', err: e2.message }; }
      } else { return { ok: false, reason: 'dl_failed', err: e.message }; }
    } else { return { ok: false, reason: 'dl_failed', err: e.message }; }
  }
  if (!dl || !dl.buffer || dl.buffer.length === 0) return { ok: false, reason: 'empty' };

  const ext = EXT_MAP[dl.contentType] || 'bin';
  const tipoStr = item.tipo || 'media';
  const fileName = `${tipoStr}_${Date.now()}.${ext}`;
  const r = await cwSendWithAttachment(conversationId, contentText || '', dl.buffer, fileName, dl.contentType);
  return { ok: r && r.status >= 200 && r.status < 300, status: r?.status, size: dl.buffer.length };
}

try {
  let contactId = input.chatwoot_contact_id;
  let conversationId = input.chatwoot_conversation_id;

  // 1. Cria ou busca contato
