        identifier: input.phone
      });
      if (createRes && createRes.payload) contactId = createRes.payload.contact.id;
    }
  }

  // 2. Busca conversa existente OU cria nova
  if (contactId && !conversationId) {
    try {
      const existingConvs = await cwRequest('GET', 'contacts/' + contactId + '/conversations', null);
      if (existingConvs && existingConvs.payload && existingConvs.payload.length > 0) {
        const openConv = existingConvs.payload.find(c => c.status === 'open') || existingConvs.payload[0];
        conversationId = openConv.id;
