        inbox_id: CW_INBOX_ID,
        status: 'open',
        additional_attributes: { agent_id: input.agent_id, source: 'cloud_api' }
      });
      if (convRes && convRes.id) conversationId = convRes.id;
    }
  }

  // 3. Envia mensagem incoming (com ou sem anexo)
  let mediaResults = [];
  if (conversationId) {
    const textContent = input.mensagem || input.text || input.mensagem_concatenada || '';
    const tipo = (input.tipo_original || input.tipo || input.tipo_final || 'texto').toLowerCase();

    // Determina lista de medias a anexar
    let mediaList = [];
    if (Array.isArray(input.media_items) && input.media_items.length > 0) {
      mediaList = input.media_items.filter(m => m && (m.media_id || m.media_url));
    } else if (input.media_url || input.media_id) {
      mediaList = [{
        media_id: input.media_id || '',
        media_url: input.media_url || '',
        tipo: tipo
      }];
    }

    // v4: predicate baseado em mediaList (robusto). Se tem media, anexa — independente do tipo
    // declarado. Tipo so e usado pra nome do arquivo.
    if (mediaList.length > 0) {
      // Envia cada media como msg separada. Primeira leva o texto/transcricao como content.
      for (let i = 0; i < mediaList.length; i++) {
        const item = mediaList[i];
        const cont = (i === 0) ? textContent : '';
        const r = await sendOneMedia(conversationId, item, cont);
        mediaResults.push({ idx: i, tipo: item.tipo, ...r });
      }
      // Se nenhum attachment subiu, fallback texto
      if (mediaResults.every(r => !r.ok)) {
        await cwRequest('POST', 'conversations/' + conversationId + '/messages', {
          content: textContent || `[${tipo} - falha ao anexar]`,
          message_type: 'incoming',
          private: false
        });
      }
    } else {
      // Texto puro
      await cwRequest('POST', 'conversations/' + conversationId + '/messages', {
        content: textContent || '[mensagem vazia]',
        message_type: 'incoming',
        private: false
      });
    }
  }

  // 4. Salva IDs no Supabase (fire-and-forget)
  if (contactId || conversationId) {
    const updateBody = {};
    if (contactId) updateBody.chatwoot_contact_id = contactId;
    if (conversationId) updateBody.chatwoot_conversation_id = conversationId;

    const sbKey = '{{SUPABASE_SERVICE_ROLE_KEY}}';
