      hostname: '{{SUPABASE_PROJECT_REF}}.supabase.co',
      path: '/rest/v1/bia_whatsapp_contacts?phone=eq.' + input.phone,
      method: 'PATCH',
      headers: { 'apikey': sbKey, 'Authorization': 'Bearer ' + sbKey, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bodyStr) },
      timeout: 5000
    });
    r.on('error', () => {});
    r.write(bodyStr);
    r.end();
  }

  return [{ json: { ...input, chatwoot_contact_id: contactId, chatwoot_conversation_id: conversationId, _synced_chatwoot: true, _media_results: mediaResults } }];
} catch (e) {
