const SB_URL = '{{SUPABASE_PROJECT_REF}}.supabase.co';
const SB_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const CLOUD_TOKEN = '{{SYSTEM_USER_TOKEN}}';
const PHONE_NUMBER_ID = '{{PHONE_NUMBER_ID}}';

function httpReq(method, host, path, headers, body) {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const opts = { method, hostname: host, path, headers: { ...headers } };
    if (data) opts.headers['Content-Length'] = Buffer.byteLength(data);
    const req = https.request(opts, (res) => {
      let buf = '';
      res.on('data', (c) => (buf += c));
      res.on('end', () => {
        try { resolve({ status: res.statusCode, data: buf ? JSON.parse(buf) : null }); }
        catch (e) { resolve({ status: res.statusCode, data: buf }); }
      });
    });
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

const blRes = await httpReq('POST', SB_URL, '/rest/v1/blacklist_api',
